@extends('admin.layout.app', ['title' => 'My Attendance'])
@section('content')
<div class="nx-card p-4 mx-auto" style="max-width:620px"><h4>Welcome, {{ $employee->full_name }}</h4><p class="text-muted">{{ now()->format('l, d F Y') }}. Your device location is required to record attendance.</p><div class="row g-3"><div class="col-6"><button id="checkIn" class="btn btn-success w-100" {{ $attendance?->check_in ? 'disabled' : '' }}>Check in{{ $attendance?->check_in ? ' · '.$attendance->check_in : '' }}</button></div><div class="col-6"><button id="checkOut" class="btn btn-primary w-100" {{ !$attendance?->check_in || $attendance?->check_out ? 'disabled' : '' }}>Check out{{ $attendance?->check_out ? ' · '.$attendance->check_out : '' }}</button></div></div><p id="attendanceMessage" class="mt-3 mb-0 text-muted"></p></div>
@endsection
@push('scripts')<script>function punch(url){if(!navigator.geolocation){$('#attendanceMessage').text('Location services are unavailable.');return;}navigator.geolocation.getCurrentPosition(function(p){$.post(url,{_token:'{{ csrf_token() }}',latitude:p.coords.latitude,longitude:p.coords.longitude,source:'browser_geolocation'}).done(function(r){$('#attendanceMessage').text(r.message);location.reload();}).fail(function(x){$('#attendanceMessage').text(x.responseJSON?.message||'Unable to record attendance.');});},function(){ $('#attendanceMessage').text('Please allow location access to continue.');},{enableHighAccuracy:true,timeout:15000});}$('#checkIn').click(()=>punch('{{ route('admin.attendance-portal.check-in') }}'));$('#checkOut').click(()=>punch('{{ route('admin.attendance-portal.check-out') }}'));</script>@endpush
